      "description": "Kayn empunha uma arma ancestral, lutando contra Rhaast, o darkin que vive dentro dela, pelo controle. Ou o Darkin triunfará ou Kayn dominará Rhaast para se tornar o Assassino das Sombras.Darkin: Cura uma porcentagem do dano de habilidades causado a Campeões.Assassino das Sombras: Causa dano adicional nos primeiros segundos em combate com Campeões inimigos.",
      "descriptionEN": "Kayn wields an ancient weapon and fights Rhaast, the darkin within it, for control. Either the Darkin will triumph, or Kayn will master Rhaast and become the Shadow Assassin.Darkin: Heal for a percentage of spell damage dealt to champions.Shadow Assassin: For the first few seconds in combat with enemy champions, deal bonus damage."
