  "Kled": {
    "name": "Kled",
    "english": "Kled",
    "range": 125,
    "resource": "Courage",
    "passive": {
      "name": "Skaarl, a Lagarto Covarde",
      "english": "Skaarl, the Cowardly Lizard",
      "description": "Kled fica em sua possante montaria, Skaarl, que toma dano por ele. Quando a Vida dela acaba, Kled desmonta.Enquanto desmontado, as habilidades de Kled mudam e ele causa menos dano a Campeões. Kled pode restaurar a coragem de Skaarl ao enfrentar inimigos. Quando a coragem chega ao máximo, Kled volta a montar em Skaarl com uma parte de sua Vida.",
      "descriptionEN": "Kled rides his trusty steed, Skaarl, who takes damage for him. When Skaarl's health depletes, Kled dismounts.While dismounted, Kled's abilities change and he deals less damage to champions. Kled can restore Skaarl's courage by fighting enemies. At maximum courage, Kled remounts with a portion of Skaarl's health."
    },
    "spells": [
      {
        "key": "Q",
        "name": "Armadilha na Corda",
        "english": "Bear Trap on a Rope",
        "description": "Kled arremessa uma armadilha de urso que causa dano e se prende a um Campeão inimigo. Caso fique preso por um curto período, o alvo recebe Dano Físico adicional e é puxado em direção a Kled.Quando desmontado, esta habilidade é substituída por Pistola de Bolso, um disparo a distância que empurra Kled para trás e restaura coragem.",
        "descriptionEN": "Kled throws a bear trap that damages and hooks an enemy champion. If shackled for a short duration, the target takes additional physical damage and is yanked toward Kled.When dismounted, this ability is replaced by Pocket Pistol, a ranged gun blast that knocks back Kled and restores courage."
      },
      {
        "key": "W",
        "name": "Tendências Violentas",
        "english": "Violent Tendencies",
        "description": "Kled recebe muita Velocidade de Ataque por quatro ataques. O quarto ataque causa mais dano.",
        "descriptionEN": "Kled gains massive attack speed for four attacks. The fourth attack deals more damage."
      },
      {
        "key": "E",
        "name": "Justar",
        "english": "Jousting",
        "description": "Kled avança, causando Dano Físico e recebendo um breve surto de velocidade. Ele pode conjurar esta habilidade novamente para recuar através do alvo inicial, causando a mesma quantidade de dano.",
        "descriptionEN": "Kled dashes, dealing physical damage and gaining a short burst of speed. Kled can cast this ability again to dash back through his initial target, dealing the same damage."
      },
      {
        "key": "R",
        "name": "Avançaaaaaaar!!!",
        "english": "Chaaaaaaaarge!!!",
        "description": "Kled e Skaarl avançam em direção a um local, deixando um rastro que concede velocidade e criando um escudo. Skaarl marca e vai de encontro ao primeiro Campeão inimigo encontrado.",
        "descriptionEN": "Kled and Skaarl charge to a location, leaving a speed-granting trail behind them and gaining a shield. Skaarl locks onto and rams the first enemy champion encountered."
      }
    ],
    "source": "https://ddragon.leagueoflegends.com/cdn/16.21.1/data/pt_BR/champion/Kled.json"
  },
  "LeeSin": {
    "name": "Lee Sin",
    "english": "Lee Sin",
    "range": 125,
    "resource": "Energy",
    "passive": {
      "name": "Agitação",
      "english": "Flurry",
      "description": "Após Lee Sin usar uma habilidade, seus próximos 2 ataques básicos recebem Velocidade de Ataque e recuperam Energia.",
      "descriptionEN": "After Lee Sin uses an ability, his next 2 basic attacks gain Attack Speed and return Energy."
    },
    "spells": [
      {
        "key": "Q",
        "name": "Onda Sônica / Ataque Ressonante",
        "english": "Sonic Wave / Resonating Strike",
        "description": "Onda Sônica: Lee Sin projeta uma onda sonora para localizar seus inimigos, causando Dano Físico ao primeiro que encontrar. Se Onda Sônica atingir um inimigo, Lee Sin pode conjurar Ataque Ressonante nos próximos 3 segundos.Ataque Ressonante: Lee Sin avança no inimigo atingido por Onda Sônica, causando Dano Físico baseado na Vida perdida do alvo.",
        "descriptionEN": "Sonic Wave: Lee Sin projects a discordant wave of sound to locate his enemies, dealing physical damage to the first enemy it encounters. If Sonic Wave hits, Lee Sin can cast Resonating Strike for the next 3 seconds.Resonating Strike: Lee Sin dashes to the enemy hit by Sonic Wave, dealing physical damage based on the target's missing Health."
      },
      {
        "key": "W",
        "name": "Proteger / Vontade de Ferro",
        "english": "Safeguard / Iron Will",
        "description": "Proteger: Lee Sin avança até um aliado-alvo, protegendo-se do dano com um Escudo. Se o aliado for um Campeão, ele também é protegido pelo Escudo. Após usar Proteger, Lee Sin pode conjurar Vontade de Ferro.Vontade de Ferro: o treinamento intenso de Lee Sin permite que ele fique mais resistente em combate. Lee Sin recebe Vampirismo Universal.",
        "descriptionEN": "Safeguard: Lee Sin rushes to target ally, shielding himself from damage. If the ally is a champion, they are also shielded. After using Safeguard, Lee Sin can cast Iron Will.Iron Will: Lee Sin's intense training allows him to thrive in battle. Lee Sin gains Omnivamp."
      },
      {
        "key": "E",
        "name": "Tempestade / Mutilar",
        "english": "Tempest / Cripple",
        "description": "Tempestade: Lee Sin golpeia o chão, enviando uma onda de choque que causa Dano Mágico e revela unidades inimigas atingidas. Se Tempestade atingir um inimigo, Lee Sin pode conjurar Mutilar.Mutilar: Lee Sin mutila inimigos próximos que tenham sido atingidos por Tempestade, reduzindo a Velocidade de Movimento deles. A Velocidade de Movimento é recuperada gradualmente ao longo da duração.",
        "descriptionEN": "Tempest: Lee Sin smashes the ground, sending out a shockwave that deals magic damage and reveals enemy units hit. If Tempest hits an enemy, Lee Sin can cast cripple.Cripple: Lee Sin cripples nearby enemies damaged by Tempest, reducing their Move Speed. Move Speed recovers gradually over the duration."
      },
      {
        "key": "R",
        "name": "Fúria do Dragão",
        "english": "Dragon's Rage",
        "description": "Lee Sin executa um poderoso chute giratório, arremessando seu alvo para trás e causando Dano Físico ao alvo e a qualquer inimigo com quem ele colidir. Esses inimigos são lançados ao ar durante um curto período. Essa técnica foi ensinada a ele por Jesse Perring, mas Lee Sin não chuta os jogadores para fora do mapa.",
        "descriptionEN": "Lee Sin performs a powerful roundhouse kick launching his target back, dealing physical damage to the target and any enemies they collide with. Enemies the target collides with are knocked into the air for a short duration. This technique was taught to him by Jesse Perring, although Lee Sin does not kick players off the map."
      }
    ],
    "source": "https://ddragon.leagueoflegends.com/cdn/16.21.1/data/pt_BR/champion/LeeSin.json"
  },
