        "key": "E",
        "name": "Frenética",
        "english": "Zoomies",
        "description": "Protege Yuumi com um Escudo e aumenta a Velocidade de Movimento e a Velocidade de Ataque. Se ela estiver conectada, isso afetará o aliado em vez dela.",
